def opciones_ubicacion():
    opciones = [f"Provincia · {nombre}" for nombre in PROVINCIAS]
    opciones += [f"Municipio · {nombre} ({provincia})" for nombre, provincia in MUNICIPIOS.items()]
    return sorted(opciones, key=str.casefold)

@lru_cache(maxsize=256)
def coordenadas_ubicacion(opcion):
    tipo, resto = opcion.split(" · ", 1)
    if tipo == "Provincia":
        latitud, longitud = PROVINCIAS[resto]
        return latitud, longitud, resto
    nombre, provincia = resto.rsplit(" (", 1)
    respuesta = requests.get("https://geocoding-api.open-meteo.com/v1/search", params={"name": nombre, "count": 10, "language": "es", "format": "json"}, timeout=10)
    respuesta.raise_for_status()
    resultado = next((dato for dato in respuesta.json().get("results", []) if dato.get("country_code") == "DO"), None)
    if resultado is None:
        raise ValueError(f"No se encontraron coordenadas para {nombre}, {provincia[:-1]}.")
    return float(resultado["latitude"]), float(resultado["longitude"]), nombre
